using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
Console.WriteLine("=== ALL ERRORS ===");
var errors = new List<(string project, string file, int line, string code, string message)>();
build.VisitAllChildren<Error>(e => {
    var project = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, e.File ?? "", e.LineNumber, e.Code ?? "", e.Text ?? ""));
});

foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine("\n\n=== ALL WARNINGS ===");
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    var project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((project, w.Code ?? "", w.Text ?? ""));
});

foreach (var g in warnings.GroupBy(w => w.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g) {
        Console.WriteLine($"  [{w.code}] {w.message}");
    }
}
EOF

