    if (n.Name?.Contains("PackageReference") == true || n.Name?.Contains("Reference") == true) {
        var project = "";
        var node = n.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  [{project}] {n.GetType().Name}: {n.Name} = {n}");
    }
});

// Look for Items
Console.WriteLine("\n=== ITEMS WITH 'Newtonsoft' or 'Package' ===");
build.VisitAllChildren<Item>(item => {
    if (item.Text?.Contains("Newtonsoft") == true || item.Text?.Contains("Package") == true || 
        item.Name?.Contains("Newtonsoft") == true || item.Name?.Contains("Package") == true) {
        Console.WriteLine($"  Item: {item.Name} -> {item.Text}");
    }
});

// Search for any text mentioning Newtonsoft
Console.WriteLine("\n=== ANYTHING WITH 'Newtonsoft' ===");
build.VisitAllChildren<BaseNode>(n => {
    var text = n.ToString();
    if (text?.Contains("Newtonsoft") == true) {
        Console.WriteLine($"  {n.GetType().Name}: {text}");
    }
});
EOF

